  p.innerHTML=`<input type="search" class="l8ssq" placeholder="جست‌وجو…" aria-label="جست‌وجو در فهرست" autocomplete="off"><div class="l8ssl" role="listbox">${O.map(o=>`<button type="button" role="option" class="l8sso" data-i="${o.i}" aria-selected="${o.i===sel.selectedIndex}"${o.dis?' disabled':''}>${esc(o.t||'—')}</button>`).join('')}</div><div class="l8sse" hidden>موردی پیدا نشد.</div>`;
  document.body.appendChild(p);L8.ss={sel,b,p};b.setAttribute('aria-expanded','true');l8SSPos();
