const L8_OKX=/\.(stl|ply|obj|zip|rar|7z|dcm|3oxz|constructioninfo|jpg|jpeg|jfif|png|webp|heic|heif|gif|bmp|tif|tiff|pdf|mp4|mov|html|htm|txt|webm|ogg|oga|m4a|mp3|wav|aac)$/i;
function l8AddFiles(list){const bad=[],big=[];let n=0;for(const f of list){if(!L8_OKX.test(f.name)){bad.push(f.name);continue}if(f.size>120*1024*1024){big.push(f.name);continue}if(!LOF.some(x=>x.name===f.name&&x.size===f.size)){LOF.push(f);n++}}
  if(bad.length||big.length)alertMsg((bad.length?'این فایل‌ها پذیرفته نمی‌شوند (نوع فایل): '+bad.join('، ')+'. مجاز: STL، PLY، OBJ، ZIP، RAR، 7Z، DCM، عکس (JPG، JFIF، PNG، WEBP، HEIC، GIF، BMP، TIF)، PDF، ویدئو MP4/MOV، صدا. ':'')+(big.length?'حجم این فایل‌ها بیش از ۱۲۰ مگابایت است: '+big.join('، '):''));
  if(n)toast(fa(n)+' فایل برای ارسال انتخاب شد.');return n}
